using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using Avalonia.Media;
using System.Text.Json;
namespace ProjectDesk;

public sealed class McpServerEditor : Window {
 public McpServerEditor(McpServerDefinition? original,IMcpSecrets secrets){
  Title=original==null?"Add MCP Server":"Edit MCP Server";Width=700;Height=740;MinWidth=560;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;
  string id=original?.Id??Guid.NewGuid().ToString();var name=new TextBox{Text=original?.Name??"",Name="ServerName"};var transport=new ComboBox{ItemsSource=new[]{"Local executable (stdio)","Remote HTTPS (Streamable HTTP)"},SelectedIndex=original?.Transport==McpConnectorTransport.RemoteHttps?1:0,HorizontalAlignment=HorizontalAlignment.Stretch};
  var address=new TextBox{Text=original?.Address??"",Name="ServerAddress",Watermark="Absolute executable path or https://server.example/mcp"};var args=new TextBox{Text=JsonSerializer.Serialize(original?.Arguments??[],new JsonSerializerOptions{WriteIndented=true}),AcceptsReturn=true,MinHeight=64};var directory=new TextBox{Text=original?.WorkingDirectory};
  var authentication=new ComboBox{ItemsSource=new[]{"None","Bearer token","Browser sign-in (OAuth)"},SelectedIndex=(int)(original?.Authentication??McpAuthentication.None),HorizontalAlignment=HorizontalAlignment.Stretch};
  var bearer=new TextBox{PasswordChar='●',Text=original==null?null:secrets.Read(id,"Bearer")};var clientId=new TextBox{Text=original?.ClientId};var scopes=new TextBox{Text=string.Join(" ",original?.Scopes??[])};var protocol=new ComboBox{ItemsSource=new[]{"Auto","2026-07-28","2025-11-25","2025-06-18"},SelectedItem=original?.ProtocolVersion??"Auto",HorizontalAlignment=HorizontalAlignment.Stretch};
  var root=new DockPanel{Margin=new Thickness(20)};var footer=new StackPanel{Spacing=8,Margin=new Thickness(0,12,0,0)};var error=new TextBlock{TextWrapping=TextWrapping.Wrap};footer.Children.Add(error);var buttons=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Spacing=8};var cancel=new Button{Content="Cancel"};var save=new Button{Content="Save Server"};save.Classes.Add("accent");buttons.Children.Add(cancel);buttons.Children.Add(save);footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
  var body=new StackPanel{Spacing=12};void Field(string label,Control input,Panel panel){var group=new StackPanel{Spacing=4};group.Children.Add(new TextBlock{Text=label,FontWeight=FontWeight.SemiBold});group.Children.Add(input);Avalonia.Automation.AutomationProperties.SetName(input,label);panel.Children.Add(group);}
  body.Children.Add(new TextBlock{Text="Server setup",FontSize=22,FontWeight=FontWeight.SemiBold});Field("Name",name,body);Field("Connection",transport,body);Field("Executable path / server URL",address,body);
  var local=new StackPanel{Spacing=12};Field("Arguments — JSON array, one value per argument",args,local);Field("Working directory (optional)",directory,local);local.Children.Add(new TextBlock{Text="For Node or Python servers, choose node.exe or python.exe and pass the server script in Arguments. Only run servers you trust. Store tokens in the environment fields below, not in arguments.",TextWrapping=TextWrapping.Wrap});
