  foreach(var key in original?.SecretEnvironmentNames??[])EnvRow(key,secrets.Read(id,"Env_"+key)??"");var addEnv=new Button{Content="Add Environment Variable"};addEnv.Click+=(_,_)=>EnvRow("","");local.Children.Add(new TextBlock{Text="Environment credentials",FontWeight=FontWeight.SemiBold});local.Children.Add(env);local.Children.Add(addEnv);body.Children.Add(local);
  var remote=new StackPanel{Spacing=12};Field("Authentication",authentication,remote);var tokenGroup=new StackPanel{Spacing=4};Field("Bearer token",bearer,tokenGroup);remote.Children.Add(tokenGroup);var oauth=new StackPanel{Spacing=12};Field("OAuth client ID (optional if the server supports registration)",clientId,oauth);Field("Scopes (space separated, optional)",scopes,oauth);oauth.Children.Add(new TextBlock{Text="Connect opens your browser when sign-in is required. OAuth sessions last until you disconnect; some providers require a registered client ID.",TextWrapping=TextWrapping.Wrap});remote.Children.Add(oauth);body.Children.Add(remote);Field("Protocol version",protocol,body);body.Children.Add(new TextBlock{Text="Tokens and environment values are stored in "+McpCredentialStore.Vault+". Server setup is saved locally. Choose Connect after saving.",TextWrapping=TextWrapping.Wrap});
  void Update(){local.IsVisible=transport.SelectedIndex==0;remote.IsVisible=!local.IsVisible;tokenGroup.IsVisible=authentication.SelectedIndex==1;oauth.IsVisible=authentication.SelectedIndex==2;}transport.SelectionChanged+=(_,_)=>Update();authentication.SelectionChanged+=(_,_)=>Update();Update();root.Children.Add(new ScrollViewer{Content=body});Content=root;
  cancel.Click+=(_,_)=>Close(null);save.Click+=(_,_)=>{try{
   var variables=local.IsVisible?envRows.Select(r=>(Name:r.Name.Text?.Trim()??"",Value:r.Value.Text??"")).ToArray():[];if(variables.Select(v=>v.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=variables.Length)throw new ArgumentException("Environment variable names must be unique.");
