   foreach(var variable in variables)if(System.Text.Encoding.Unicode.GetByteCount(variable.Value)>2560)throw new ArgumentException("An environment credential exceeds 2,560 bytes.");if(value.Authentication==McpAuthentication.BearerToken)secrets.Write(id,"Bearer",bearer.Text!);else secrets.Remove(id,"Bearer");foreach(var variable in variables)secrets.Write(id,"Env_"+variable.Name,variable.Value);foreach(var old in original?.SecretEnvironmentNames??[])if(!variables.Any(v=>v.Name==old))secrets.Remove(id,"Env_"+old);Close(value);
  }catch(Exception ex){error.Text=ex.Message;}};UiIcons.ApplyTo(this);
